    public static class BuildInfo {
#if BETA
        public static readonly string Channel="beta";
#else
        public static readonly string Channel="main";
#endif
        public static string Version { get { var value=Assembly.GetExecutingAssembly().GetCustomAttributes(typeof(AssemblyInformationalVersionAttribute),false).OfType<AssemblyInformationalVersionAttribute>().FirstOrDefault();return value==null?"1.0.0":value.InformationalVersion; } }
