    public sealed class UpdateInfo { public string Version,DownloadUrl,Digest,Notes; }
    public static class AutoUpdater {
        const string ApiRoot="https://api.github.com/repos/ls1808/ssh-manager/releases";
        const string AssetName="SSH-Manager.exe";
        static WebClient Client(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var client=new WebClient();client.Headers[HttpRequestHeader.UserAgent]="SSH-Manager/"+BuildInfo.Version;client.Headers[HttpRequestHeader.Accept]="application/vnd.github+json";return client;}
        static Dictionary<string,object> ObjectMap(object value){return value as Dictionary<string,object>;}
        static string Value(Dictionary<string,object> map,string key){object value;return map!=null&&map.TryGetValue(key,out value)&&value!=null?value.ToString():"";}
        static bool Bool(Dictionary<string,object> map,string key){object value;return map!=null&&map.TryGetValue(key,out value)&&value is bool&&(bool)value;}
        public static async Task<UpdateInfo> FindAsync(){
            string json;using(var client=Client())json=await client.DownloadStringTaskAsync(BuildInfo.Channel=="beta"?ApiRoot+"?per_page=30":ApiRoot+"/latest");var serializer=new JavaScriptSerializer();Dictionary<string,object> release=null;
            if(BuildInfo.Channel=="beta"){var releases=serializer.DeserializeObject(json) as object[];if(releases!=null)foreach(var raw in releases){var candidate=ObjectMap(raw);if(candidate!=null&&!Bool(candidate,"draft")&&Bool(candidate,"prerelease")){release=candidate;break;}}}else release=ObjectMap(serializer.DeserializeObject(json));
            if(release==null)return null;string version=Value(release,"tag_name").TrimStart('v','V');if(CompareVersions(version,BuildInfo.Version)<=0)return null;object assetsRaw;if(!release.TryGetValue("assets",out assetsRaw))return null;var assets=assetsRaw as object[];Dictionary<string,object> executable=null,checksum=null;if(assets!=null)foreach(var raw in assets){var asset=ObjectMap(raw);string name=Value(asset,"name");if(name.Equals(AssetName,StringComparison.OrdinalIgnoreCase))executable=asset;else if(name.Equals(AssetName+".sha256",StringComparison.OrdinalIgnoreCase))checksum=asset;}if(executable==null)return null;
            string digest=Value(executable,"digest");if(digest.StartsWith("sha256:",StringComparison.OrdinalIgnoreCase))digest=digest.Substring(7);if(string.IsNullOrWhiteSpace(digest)&&checksum!=null){using(var client=Client())digest=(await client.DownloadStringTaskAsync(Value(checksum,"browser_download_url"))).Split(new[]{' ','\r','\n','\t'},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"";}
            return new UpdateInfo{Version=version,DownloadUrl=Value(executable,"browser_download_url"),Digest=digest.Trim(),Notes=Value(release,"body")};
        }
        public static async Task<string> DownloadAsync(UpdateInfo update){string path=Path.Combine(Path.GetTempPath(),"SSH-Manager-"+Guid.NewGuid().ToString("N")+".exe");using(var client=Client())await client.DownloadFileTaskAsync(update.DownloadUrl,path);if(string.IsNullOrWhiteSpace(update.Digest))throw new InvalidDataException("The release does not include a SHA-256 digest.");string actual;using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))actual=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();if(!actual.Equals(update.Digest,StringComparison.OrdinalIgnoreCase)){try{File.Delete(path);}catch{}throw new InvalidDataException("The downloaded update failed its SHA-256 integrity check.");}return path;}
        public static int CompareVersions(string left,string right){string[] a=(left??"").TrimStart('v','V').Split(new[]{'-'},2),b=(right??"").TrimStart('v','V').Split(new[]{'-'},2);var an=a[0].Split('.');var bn=b[0].Split('.');for(int i=0;i<Math.Max(an.Length,bn.Length);i++){int av=0,bv=0;if(i<an.Length)int.TryParse(an[i],out av);if(i<bn.Length)int.TryParse(bn[i],out bv);if(av!=bv)return av.CompareTo(bv);}bool ap=a.Length>1,bp=b.Length>1;if(ap!=bp)return ap?-1:1;if(!ap)return 0;return ComparePrerelease(a[1],b[1]);}
        static int ComparePrerelease(string left,string right){var a=left.Split('.');var b=right.Split('.');for(int i=0;i<Math.Max(a.Length,b.Length);i++){if(i>=a.Length)return -1;if(i>=b.Length)return 1;int av,bv;bool ai=int.TryParse(a[i],out av),bi=int.TryParse(b[i],out bv);int c=ai&&bi?av.CompareTo(bv):ai?-1:bi?1:string.Compare(a[i],b[i],StringComparison.OrdinalIgnoreCase);if(c!=0)return c;}return 0;}
        public static void StartInstaller(string downloadedPath){string target=Process.GetCurrentProcess().MainModule.FileName;var start=new ProcessStartInfo(downloadedPath,"--apply-update \""+target+"\" "+Process.GetCurrentProcess().Id){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(downloadedPath)};Process.Start(start);}
        static void ReplaceExecutable(string source,string target){string backup=target+".previous";Exception last=null;for(int attempt=0;attempt<30;attempt++){try{if(File.Exists(target))File.Copy(target,backup,true);File.Copy(source,target,true);last=null;break;}catch(Exception ex){last=ex;Thread.Sleep(500);}}if(last!=null)throw last;}
        public static void ValidateReplacement(){string root=Path.Combine(Path.GetTempPath(),"ssh-manager-update-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string source=Path.Combine(root,"new.exe"),target=Path.Combine(root,"app.exe");File.WriteAllText(source,"new-version");File.WriteAllText(target,"old-version");ReplaceExecutable(source,target);if(File.ReadAllText(target)!="new-version"||File.ReadAllText(target+".previous")!="old-version")throw new InvalidOperationException("Update replacement did not preserve and replace the expected files.");}finally{try{Directory.Delete(root,true);}catch{}}}
        public static void ApplyUpdate(string source,string target,int processId){try{try{Process.GetProcessById(processId).WaitForExit(60000);}catch{}ReplaceExecutable(source,target);Process.Start(new ProcessStartInfo(target,"--cleanup-update \""+source+"\""){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(target)});}catch(Exception ex){try{File.WriteAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"SSH Manager","update-error.log"),DateTime.Now+Environment.NewLine+ex);}catch{}try{if(File.Exists(target))Process.Start(target);}catch{}}}
    }

    public sealed class ConPtySession : IDisposable {
        const uint EXTENDED_STARTUPINFO_PRESENT=0x00080000;
        static readonly IntPtr PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE=(IntPtr)0x00020016;
        IntPtr pseudoConsole,processHandle; FileStream input,output; Thread reader,waiter; readonly object writeLock=new object(); bool closed;int endedSignaled;
        public event Action<string> Output; public event Action Ended;

        [StructLayout(LayoutKind.Sequential)] struct COORD{public short X,Y;public COORD(short x,short y){X=x;Y=y;}}
        [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct STARTUPINFO{public int cb;public string reserved,desktop,title;public int x,y,xSize,ySize,xChars,yChars,fillAttribute,flags;public short showWindow,reserved2;public IntPtr reservedPtr,stdInput,stdOutput,stdError;}
        [StructLayout(LayoutKind.Sequential)] struct STARTUPINFOEX{public STARTUPINFO StartupInfo;public IntPtr AttributeList;}
        [StructLayout(LayoutKind.Sequential)] struct PROCESS_INFORMATION{public IntPtr Process,Thread;public uint ProcessId,ThreadId;}
        [StructLayout(LayoutKind.Sequential)] struct SECURITY_ATTRIBUTES{public int Length;public IntPtr SecurityDescriptor;public int InheritHandle;}
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool CreatePipe(out IntPtr read,out IntPtr write,IntPtr attributes,uint size);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool CloseHandle(IntPtr handle);
        [DllImport("kernel32.dll",SetLastError=true)] static extern int CreatePseudoConsole(COORD size,IntPtr input,IntPtr output,uint flags,out IntPtr pseudoConsole);
        [DllImport("kernel32.dll")] static extern void ClosePseudoConsole(IntPtr pseudoConsole);
        [DllImport("kernel32.dll",SetLastError=true)] static extern int ResizePseudoConsole(IntPtr pseudoConsole,COORD size);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool InitializeProcThreadAttributeList(IntPtr list,int count,int flags,ref IntPtr size);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool UpdateProcThreadAttribute(IntPtr list,uint flags,IntPtr attribute,IntPtr value,IntPtr size,IntPtr previous,IntPtr returnedSize);
        [DllImport("kernel32.dll")] static extern void DeleteProcThreadAttributeList(IntPtr list);
        [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool CreateProcess(string application,string commandLine,ref SECURITY_ATTRIBUTES processAttributes,ref SECURITY_ATTRIBUTES threadAttributes,bool inheritHandles,uint flags,IntPtr environment,string currentDirectory,ref STARTUPINFOEX startup,out PROCESS_INFORMATION process);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool TerminateProcess(IntPtr process,uint exitCode);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetExitCodeProcess(IntPtr process,out uint exitCode);
        [DllImport("kernel32.dll",SetLastError=true)] static extern uint WaitForSingleObject(IntPtr handle,uint milliseconds);

        public ConPtySession(string commandLine,int columns,int rows){
            IntPtr ptyInput=IntPtr.Zero,hostInput=IntPtr.Zero,hostOutput=IntPtr.Zero,ptyOutput=IntPtr.Zero,attributeList=IntPtr.Zero;
            try{
                if(!CreatePipe(out ptyInput,out hostInput,IntPtr.Zero,0)||!CreatePipe(out hostOutput,out ptyOutput,IntPtr.Zero,0))throw new Win32Exception(Marshal.GetLastWin32Error(),"Creating ConPTY pipes failed");
                int result=CreatePseudoConsole(new COORD((short)Math.Max(20,columns),(short)Math.Max(5,rows)),ptyInput,ptyOutput,0,out pseudoConsole);if(result!=0)Marshal.ThrowExceptionForHR(result);
                CloseHandle(ptyInput);ptyInput=IntPtr.Zero;CloseHandle(ptyOutput);ptyOutput=IntPtr.Zero;
                input=new FileStream(new SafeFileHandle(hostInput,true),FileAccess.Write,4096,false);hostInput=IntPtr.Zero;
                output=new FileStream(new SafeFileHandle(hostOutput,true),FileAccess.Read,4096,false);hostOutput=IntPtr.Zero;
                var startup=new STARTUPINFOEX();startup.StartupInfo.cb=Marshal.SizeOf(typeof(STARTUPINFOEX));IntPtr bytes=IntPtr.Zero;InitializeProcThreadAttributeList(IntPtr.Zero,1,0,ref bytes);attributeList=Marshal.AllocHGlobal(bytes);if(!InitializeProcThreadAttributeList(attributeList,1,0,ref bytes))throw new Win32Exception(Marshal.GetLastWin32Error(),"Preparing ConPTY process attributes failed");startup.AttributeList=attributeList;if(!UpdateProcThreadAttribute(attributeList,0,PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE,pseudoConsole,(IntPtr)IntPtr.Size,IntPtr.Zero,IntPtr.Zero))throw new Win32Exception(Marshal.GetLastWin32Error(),"Attaching the pseudoconsole failed");
                var processSecurity=new SECURITY_ATTRIBUTES{Length=Marshal.SizeOf(typeof(SECURITY_ATTRIBUTES))};var threadSecurity=new SECURITY_ATTRIBUTES{Length=Marshal.SizeOf(typeof(SECURITY_ATTRIBUTES))};PROCESS_INFORMATION process;if(!CreateProcess(null,commandLine,ref processSecurity,ref threadSecurity,false,EXTENDED_STARTUPINFO_PRESENT,IntPtr.Zero,null,ref startup,out process))throw new Win32Exception(Marshal.GetLastWin32Error(),"Starting the terminal process failed: "+commandLine);processHandle=process.Process;CloseHandle(process.Thread);
                reader=new Thread(ReadLoop);reader.IsBackground=true;reader.Name="SSH Manager terminal output";waiter=new Thread(WaitLoop);waiter.IsBackground=true;waiter.Name="SSH Manager terminal process";
            }catch{Dispose();throw;}finally{if(attributeList!=IntPtr.Zero){DeleteProcThreadAttributeList(attributeList);Marshal.FreeHGlobal(attributeList);}if(ptyInput!=IntPtr.Zero)CloseHandle(ptyInput);if(ptyOutput!=IntPtr.Zero)CloseHandle(ptyOutput);if(hostInput!=IntPtr.Zero)CloseHandle(hostInput);if(hostOutput!=IntPtr.Zero)CloseHandle(hostOutput);}
        }
        public void Start(){if(reader!=null&&!reader.IsAlive)reader.Start();if(waiter!=null&&!waiter.IsAlive)waiter.Start();}
        void ReadLoop(){try{var decoder=Encoding.UTF8.GetDecoder();var bytes=new byte[8192];var chars=new char[8192];for(;;){int count=output.Read(bytes,0,bytes.Length);if(count<=0)break;int used=decoder.GetChars(bytes,0,count,chars,0,false);if(used>0){var text=new string(chars,0,used);if(text.Contains("\x1b[6n"))Send("\x1b[1;1R");var handler=Output;if(handler!=null)handler(text);}}}catch{}finally{SignalEnded();}}
        void WaitLoop(){try{if(processHandle!=IntPtr.Zero)WaitForSingleObject(processHandle,0xFFFFFFFF);}catch{}finally{SignalEnded();}}
        void SignalEnded(){if(Interlocked.Exchange(ref endedSignaled,1)!=0)return;var handler=Ended;if(handler!=null)handler();}
        public void Send(string text){if(closed||input==null)return;var data=Encoding.UTF8.GetBytes(text);lock(writeLock){try{input.Write(data,0,data.Length);input.Flush();}catch{}}}
        public void Resize(int columns,int rows){if(closed||pseudoConsole==IntPtr.Zero)return;try{ResizePseudoConsole(pseudoConsole,new COORD((short)Math.Max(20,Math.Min(300,columns)),(short)Math.Max(5,Math.Min(120,rows))));}catch{}}
        public void Dispose(){if(closed)return;closed=true;try{if(processHandle!=IntPtr.Zero){uint code;if(GetExitCodeProcess(processHandle,out code)&&code==259)TerminateProcess(processHandle,0);}}catch{}try{if(input!=null)input.Dispose();}catch{}try{if(pseudoConsole!=IntPtr.Zero)ClosePseudoConsole(pseudoConsole);}catch{}try{if(output!=null)output.Dispose();}catch{}if(processHandle!=IntPtr.Zero)CloseHandle(processHandle);processHandle=IntPtr.Zero;pseudoConsole=IntPtr.Zero;}
    }

    public static class Program {
        [STAThread] public static void Main(string[] args) {
            if(args.Length>2&&args[0]=="--apply-update"){int pid;if(!int.TryParse(args[2],out pid))pid=0;AutoUpdater.ApplyUpdate(Process.GetCurrentProcess().MainModule.FileName,args[1],pid);return;}
            if(args.Length>1&&args[0]=="--cleanup-update"){string cleanup=args[1];Task.Run(()=>{Thread.Sleep(1500);for(int i=0;i<20&&File.Exists(cleanup);i++){try{File.Delete(cleanup);}catch{}Thread.Sleep(500);}});args=new string[0];}
            if(args.Length>0 && args[0]=="--askpass") { using(var w=new StreamWriter(Console.OpenStandardOutput())) { w.WriteLine(Environment.GetEnvironmentVariable("SSH_MANAGER_PASSWORD")??""); } return; }
            if(args.Length>0 && args[0]=="--conpty-test") { var received=new ManualResetEvent(false);var captured=new StringBuilder();string shell=Environment.GetEnvironmentVariable("ComSpec")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"cmd.exe");using(var session=new ConPtySession("\""+shell+"\" /d /q",80,24)){session.Output+=s=>{captured.Append(s);if(captured.ToString().Contains("CONPTY_OK"))received.Set();};session.Start();Thread.Sleep(250);session.Send("echo CONPTY_OK\r");received.WaitOne(5000);session.Send("exit\r");}bool ok=captured.ToString().Contains("CONPTY_OK");string result=ok?"ConPTY bidirectional integration passed.":"ConPTY integration failed.";if(args.Length>1)File.WriteAllText(args[1],result);else Console.WriteLine(result);Environment.ExitCode=ok?0:2;return; }
            var app=new Application(); var controller=new Controller();
            if(args.Length>1 && args[0]=="--screenshot") controller.ScreenshotPath=args[1];
            if(args.Length>0 && args[0]=="--validate") { controller.ValidateOnly=true; }
            app.Run(controller.Build());
        }
    }

