        public Window Build() {
            window=(Window)XamlReader.Parse(Xaml); Find(); LoadBrandIcon(); Hook(); Load(); Refresh(); if(hosts.Items.Count>0)hosts.SelectedIndex=0;
            if(ValidateOnly) window.Loaded+=(s,e)=>{OpenCommandMenu();if(commandMenu==null||commandMenu.Items.Count<2)throw new InvalidOperationException("Command menu validation failed.");if(PrepareCommand("cp <source> <destination>")!="cp "||PrepareCommand("systemctl status <service>")!="systemctl status ")throw new InvalidOperationException("Command placeholder validation failed.");if(AutoUpdater.CompareVersions("1.1.0","1.0.9")<=0||AutoUpdater.CompareVersions("1.1.0-beta.2","1.1.0-beta.1")<=0||AutoUpdater.CompareVersions("1.1.0","1.1.0-beta.9")<=0)throw new InvalidOperationException("Update version validation failed.");AutoUpdater.ValidateReplacement();commandMenu.IsOpen=false;Console.WriteLine("SSH Manager WPF, command menu, and updater validation passed.");window.Close();};
            if(!string.IsNullOrEmpty(ScreenshotPath)) window.Loaded+=(s,e)=>Screenshot();
            if(!ValidateOnly&&string.IsNullOrEmpty(ScreenshotPath))window.Loaded+=(s,e)=>CheckForUpdate();
            return window;
        }

        T N<T>(string n) where T:class { return window.FindName(n) as T; }
        async void CheckForUpdate(){try{await Task.Delay(1200);var update=await AutoUpdater.FindAsync();if(update==null)return;string channel=BuildInfo.Channel=="beta"?"Beta":"Stable";var answer=MessageBox.Show(window,"SSH Manager "+update.Version+" is available on the "+channel+" channel.\n\nInstall it now? The app will restart automatically.","SSH Manager update available",MessageBoxButton.YesNo,MessageBoxImage.Information);if(answer!=MessageBoxResult.Yes)return;window.Cursor=Cursors.Wait;string downloaded=await AutoUpdater.DownloadAsync(update);AutoUpdater.StartInstaller(downloaded);Application.Current.Shutdown();}catch(Exception ex){window.Cursor=Cursors.Arrow;if(ex is WebException)return;MessageBox.Show(window,"The update could not be installed.\n\n"+ex.Message,"Update failed",MessageBoxButton.OK,MessageBoxImage.Warning);}}
