        [DllImport("dwmapi.dll")] static extern int DwmSetWindowAttribute(IntPtr hwnd,int attribute,ref int value,int size);
        [DllImport("user32.dll")] static extern IntPtr MonitorFromWindow(IntPtr hwnd,uint flags);
        [DllImport("user32.dll",CharSet=CharSet.Auto)] static extern bool GetMonitorInfo(IntPtr monitor,ref MONITORINFO info);
        [StructLayout(LayoutKind.Sequential)] struct POINT{public int X,Y;}
        [StructLayout(LayoutKind.Sequential)] struct MINMAXINFO{public POINT Reserved,MaxSize,MaxPosition,MinTrackSize,MaxTrackSize;}
        [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Auto)] struct MONITORINFO{public int Size;public RECT Monitor,Work;public uint Flags;}
        [StructLayout(LayoutKind.Sequential)] struct RECT{public int Left,Top,Right,Bottom;}
        void InitializeNativeWindow(){try{var helper=new WindowInteropHelper(window);var source=HwndSource.FromHwnd(helper.Handle);if(source!=null)source.AddHook(WindowMessage);int preference=2;DwmSetWindowAttribute(helper.Handle,33,ref preference,sizeof(int));}catch{}}
        IntPtr WindowMessage(IntPtr hwnd,int message,IntPtr wParam,IntPtr lParam,ref bool handled){const int WM_GETMINMAXINFO=0x24;if(message==WM_GETMINMAXINFO){var monitor=MonitorFromWindow(hwnd,2);if(monitor!=IntPtr.Zero){var info=new MONITORINFO();info.Size=Marshal.SizeOf(typeof(MONITORINFO));if(GetMonitorInfo(monitor,ref info)){var limits=(MINMAXINFO)Marshal.PtrToStructure(lParam,typeof(MINMAXINFO));limits.MaxPosition.X=info.Work.Left-info.Monitor.Left;limits.MaxPosition.Y=info.Work.Top-info.Monitor.Top;limits.MaxSize.X=info.Work.Right-info.Work.Left;limits.MaxSize.Y=info.Work.Bottom-info.Work.Top;limits.MaxTrackSize=limits.MaxSize;Marshal.StructureToPtr(limits,lParam,true);handled=true;}}}return IntPtr.Zero;}
        void Responsive(){bool compact=window.ActualWidth<1240,narrow=window.ActualWidth<980;if(compact&&!lastCompact)compactSidebarOpen=false;if(narrow&&!lastNarrow)compactDetailsOpen=false;if(!compact)compactSidebarOpen=true;if(!narrow)compactDetailsOpen=true;workspaceToggle.Visibility=compact?Visibility.Visible:Visibility.Collapsed;infoToggle.Visibility=narrow?Visibility.Visible:Visibility.Collapsed;if(!compact){workspaceColumn.Width=new GridLength(205);workspacePanel.Visibility=Visibility.Visible;workspacePanel.Width=double.NaN;workspacePanel.HorizontalAlignment=HorizontalAlignment.Stretch;Grid.SetColumn(workspacePanel,0);Grid.SetColumnSpan(workspacePanel,1);Panel.SetZIndex(workspacePanel,0);}else{workspaceColumn.Width=new GridLength(0);workspacePanel.Visibility=compactSidebarOpen?Visibility.Visible:Visibility.Collapsed;workspacePanel.Width=220;workspacePanel.HorizontalAlignment=HorizontalAlignment.Left;Grid.SetColumn(workspacePanel,0);Grid.SetColumnSpan(workspacePanel,2);Panel.SetZIndex(workspacePanel,20);}if(!narrow){detailColumn.Width=new GridLength(compact?320:350);detailsPanel.Visibility=Visibility.Visible;detailsPanel.Width=double.NaN;detailsPanel.HorizontalAlignment=HorizontalAlignment.Stretch;Grid.SetColumn(detailsPanel,2);Grid.SetColumnSpan(detailsPanel,1);Panel.SetZIndex(detailsPanel,0);}else{detailColumn.Width=new GridLength(0);detailsPanel.Visibility=compactDetailsOpen?Visibility.Visible:Visibility.Collapsed;detailsPanel.Width=340;detailsPanel.HorizontalAlignment=HorizontalAlignment.Right;Grid.SetColumn(detailsPanel,1);Grid.SetColumnSpan(detailsPanel,2);Panel.SetZIndex(detailsPanel,19);}lastCompact=compact;lastNarrow=narrow;}
        void CloseCompactDrawerOnOutsideClick(object sender,MouseButtonEventArgs e){DependencyObject source=e.OriginalSource as DependencyObject;bool changed=false;if(window.ActualWidth<1240&&compactSidebarOpen&&!IsInside(source,workspacePanel)&&!IsInside(source,workspaceToggle)){compactSidebarOpen=false;changed=true;}if(window.ActualWidth<980&&compactDetailsOpen&&!IsInside(source,detailsPanel)&&!IsInside(source,infoToggle)){compactDetailsOpen=false;changed=true;}if(changed)Responsive();}
        bool IsInside(DependencyObject source,DependencyObject container){for(var d=source;d!=null;){if(d==container)return true;DependencyObject parent=null;try{parent=VisualTreeHelper.GetParent(d);}catch{parent=LogicalTreeHelper.GetParent(d);}d=parent;}return false;}
        void SelectHostFromClick(object sender,MouseButtonEventArgs e){DependencyObject d=e.OriginalSource as DependencyObject;while(d!=null&&!(d is ListBoxItem))d=VisualTreeHelper.GetParent(d);var item=d as ListBoxItem;if(item!=null)hosts.SelectedItem=item.Content;}
        void ConnectHostFromDoubleClick(object sender,MouseButtonEventArgs e){DependencyObject d=e.OriginalSource as DependencyObject;while(d!=null&&d!=hosts){if(d is Button)return;if(d is ListBoxItem){hosts.SelectedItem=((ListBoxItem)d).Content;Launch(false);e.Handled=true;return;}d=VisualTreeHelper.GetParent(d);}}

