        MenuItem StyledMenuItem(string header,string tooltip){var item=new MenuItem{Header=header,Style=(Style)window.FindResource("CommandMenuItem")};if(!string.IsNullOrWhiteSpace(tooltip))item.ToolTip=tooltip;return item;}
        void OpenCommandMenu(){
            commandMenu=new ContextMenu{Style=(Style)window.FindResource("CommandContextMenu"),MaxHeight=560};
            var recent=StyledMenuItem("Recently Used",null);recent.IsEnabled=recentCommands.Count>0;foreach(var value in recentCommands){var chosen=value;var item=StyledMenuItem(chosen,null);item.Click+=(s,e)=>PasteCommand(chosen);recent.Items.Add(item);}commandMenu.Items.Add(recent);commandMenu.Items.Add(new Separator{Style=(Style)window.FindResource("CommandSeparator")});
            foreach(var group in LinuxCommands().GroupBy(x=>x.Category)){
                var category=StyledMenuItem(group.Key,null);
                foreach(var entry in group){var command=StyledMenuItem(entry.Name,entry.Description);foreach(var choice in entry.Choices){var chosen=choice;var variant=StyledMenuItem(chosen,null);variant.Click+=(s,e)=>PasteCommand(chosen);command.Items.Add(variant);}category.Items.Add(command);}commandMenu.Items.Add(category);
            }
            commandButton.ContextMenu=commandMenu;commandMenu.PlacementTarget=commandButton;commandMenu.Placement=System.Windows.Controls.Primitives.PlacementMode.Bottom;commandMenu.IsOpen=true;
        }
        string PrepareCommand(string command){string source=command??"";bool hadPlaceholder=Regex.IsMatch(source,"<[^<>]+>");string pasted=Regex.Replace(source,@"(?<!\S)\S*<[^<>]+>\S*","");pasted=Regex.Replace(pasted,@"[ \t]{2,}"," ").TrimEnd();if(hadPlaceholder&&pasted.Length>0)pasted+=" ";return pasted;}
