        void OpenTerminal(Connection connection,bool sftp){
            TerminalState state=null;try{
                state=CreateTerminalView(connection,sftp);var command=BuildTerminalCommand(connection,sftp);state.Session=new ConPtySession(command,100,30);state.Session.Output+=text=>window.Dispatcher.BeginInvoke(new Action(()=>AppendTerminal(state,text)));state.Session.Ended+=()=>window.Dispatcher.BeginInvoke(new Action(()=>TerminalEnded(state)));state.Session.Start();
                terminalSessions[state.Tab]=state;terminalTabs.Items.Add(state.Tab);terminalTabs.SelectedItem=state.Tab;UpdateTerminalCount();mainGrid.Visibility=Visibility.Collapsed;terminalWorkspace.Visibility=Visibility.Visible;state.Output.Focus();connection.LastConnected=DateTime.UtcNow.ToString("o");Save();
            }catch(Exception ex){if(state!=null&&state.Session!=null)state.Session.Dispose();MessageBox.Show(window,"The internal terminal could not start.\n\n"+ex.Message+"\n\nWindows 10 version 1809 or newer is required for ConPTY.","Could not open terminal",MessageBoxButton.OK,MessageBoxImage.Error);}
        }
        TerminalState CreateTerminalView(Connection connection,bool sftp){
            var state=new TerminalState{Connection=connection,Sftp=sftp};if(connection.AuthType=="Password"&&!string.IsNullOrEmpty(connection.EncryptedPassword))try{state.SavedPassword=Unprotect(connection.EncryptedPassword);}catch{}
            var tab=new TabItem();state.Tab=tab;var header=new StackPanel{Orientation=Orientation.Horizontal};header.Children.Add(new TextBlock{Text=(sftp?"SFTP  ":"")+connection.Name,Foreground=(Brush)window.FindResource("Text"),VerticalAlignment=VerticalAlignment.Center,MaxWidth=170,TextTrimming=TextTrimming.CharacterEllipsis});var close=new Button{Content="×",Width=24,Height=22,Margin=new Thickness(9,0,0,0),Padding=new Thickness(0),Foreground=(Brush)window.FindResource("Danger"),Background=Brushes.Transparent,BorderThickness=new Thickness(0),Cursor=Cursors.Hand,FontSize=15};close.Click+=(s,e)=>{e.Handled=true;CloseTerminal(tab);};header.Children.Add(close);tab.Header=header;
            var shell=new Grid{Margin=new Thickness(0),Background=new SolidColorBrush(Color.FromRgb(11,12,16))};
            var output=new TextBox{IsReadOnly=true,IsReadOnlyCaretVisible=true,Focusable=true,AcceptsReturn=true,AcceptsTab=true,TextWrapping=TextWrapping.Wrap,VerticalContentAlignment=VerticalAlignment.Top,VerticalAlignment=VerticalAlignment.Stretch,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,FontFamily=new FontFamily("Cascadia Mono, Consolas"),FontSize=13,Background=new SolidColorBrush(Color.FromRgb(13,14,19)),Foreground=new SolidColorBrush(Color.FromRgb(225,226,231)),BorderBrush=new SolidColorBrush(Color.FromRgb(52,53,64)),Padding=new Thickness(16),CaretBrush=(Brush)window.FindResource("Accent"),Cursor=Cursors.IBeam};state.Output=output;shell.Children.Add(output);
            output.PreviewTextInput+=(s,e)=>{if(!state.Ended&&state.Session!=null){state.Session.Send(e.Text);e.Handled=true;}};output.PreviewKeyDown+=(s,e)=>TerminalKey(state,e);output.PreviewMouseLeftButtonDown+=(s,e)=>{output.Focus();output.Select(Math.Max(0,Math.Min(state.Cursor,output.Text.Length)),0);e.Handled=true;};output.GotKeyboardFocus+=(s,e)=>output.Select(Math.Max(0,Math.Min(state.Cursor,output.Text.Length)),0);shell.SizeChanged+=(s,e)=>{if(state.Session!=null)state.Session.Resize((int)Math.Max(20,shell.ActualWidth/8.2),(int)Math.Max(5,shell.ActualHeight/17));};tab.Content=shell;return state;
        }
        void TerminalKey(TerminalState state,KeyEventArgs e){if(state.Ended||state.Session==null)return;bool ctrl=(Keyboard.Modifiers&ModifierKeys.Control)!=0,shift=(Keyboard.Modifiers&ModifierKeys.Shift)!=0;if(ctrl&&(e.Key==Key.V)){if(Clipboard.ContainsText())state.Session.Send(Clipboard.GetText());e.Handled=true;return;}if(ctrl&&e.Key>=Key.A&&e.Key<=Key.Z){state.Session.Send(((char)((int)e.Key-(int)Key.A+1)).ToString());e.Handled=true;return;}string sequence=null;switch(e.Key){case Key.Enter:sequence="\r";break;case Key.Back:sequence="\x7f";break;case Key.Tab:sequence="\t";break;case Key.Escape:sequence="\x1b";break;case Key.Up:sequence="\x1b[A";break;case Key.Down:sequence="\x1b[B";break;case Key.Right:sequence="\x1b[C";break;case Key.Left:sequence="\x1b[D";break;case Key.Home:sequence="\x1b[H";break;case Key.End:sequence="\x1b[F";break;case Key.Delete:sequence="\x1b[3~";break;case Key.PageUp:sequence="\x1b[5~";break;case Key.PageDown:sequence="\x1b[6~";break;}if(sequence!=null){state.Session.Send(sequence);e.Handled=true;}}
        void AppendTerminal(TerminalState state,string raw){
            if(state.Ended||state.Output==null)return;ProcessTerminalStream(state,raw);
            if(state.Screen.Length>300000){int remove=state.Screen.Length-240000;int newline=state.Screen.ToString().IndexOf('\n',remove);if(newline>=0)remove=newline+1;state.Screen.Remove(0,remove);state.Cursor=Math.Max(0,state.Cursor-remove);state.SavedCursor=Math.Max(0,state.SavedCursor-remove);}
            state.Cursor=Math.Max(0,Math.Min(state.Cursor,state.Screen.Length));state.Output.Text=state.Screen.ToString();
            if(state.Output.IsKeyboardFocusWithin){state.Output.Select(state.Cursor,0);int line=state.Output.GetLineIndexFromCharacterIndex(state.Cursor);if(line>=0)state.Output.ScrollToLine(line);}
            var lower=CsiSequence.Replace(raw,"").ToLowerInvariant();if((lower.Contains("password:")||lower.Contains("passphrase for key"))&&!state.SavedPasswordSent&&!string.IsNullOrEmpty(state.SavedPassword)){state.SavedPasswordSent=true;state.Session.Send(state.SavedPassword+"\r");state.SavedPassword=null;}
        }
        void ProcessTerminalStream(TerminalState state,string raw){
            string text=state.PendingAnsi+(raw??"");state.PendingAnsi="";int i=0;
            while(i<text.Length){char c=text[i];
                if(c=='\x1b'){
                    if(i+1>=text.Length){state.PendingAnsi=text.Substring(i);break;}
                    if(text[i+1]=='['){int end=i+2;while(end<text.Length&&(text[end]<'@'||text[end]>'~'))end++;if(end>=text.Length){state.PendingAnsi=text.Substring(i);break;}HandleCsi(state,text.Substring(i+2,end-i-2),text[end]);i=end+1;continue;}
                    if(text[i+1]==']'){int end=i+2;while(end<text.Length&&text[end]!='\a'&&!(text[end]=='\x1b'&&end+1<text.Length&&text[end+1]=='\\'))end++;if(end>=text.Length){state.PendingAnsi=text.Substring(i);break;}i=end+(text[end]=='\x1b'?2:1);continue;}
                    i+=2;continue;
                }
                if(c=='\r'){state.Cursor=TerminalLineStart(state.Screen,state.Cursor);i++;continue;}
                if(c=='\n'){int end=TerminalLineEnd(state.Screen,state.Cursor);if(end<state.Screen.Length)state.Cursor=end+1;else{state.Screen.Append('\n');state.Cursor=state.Screen.Length;}i++;continue;}
                if(c=='\b'){state.Cursor=Math.Max(TerminalLineStart(state.Screen,state.Cursor),state.Cursor-1);i++;continue;}
                if(c=='\t'){int column=state.Cursor-TerminalLineStart(state.Screen,state.Cursor),spaces=8-(column%8);while(spaces-->0)WriteTerminalChar(state,' ');i++;continue;}
                if(c>=' '&&c!='\x7f')WriteTerminalChar(state,c);i++;
            }
        }
        static int TerminalLineStart(StringBuilder b,int cursor){cursor=Math.Max(0,Math.Min(cursor,b.Length));for(int i=cursor-1;i>=0;i--)if(b[i]=='\n')return i+1;return 0;}
        static int TerminalLineEnd(StringBuilder b,int cursor){cursor=Math.Max(0,Math.Min(cursor,b.Length));for(int i=cursor;i<b.Length;i++)if(b[i]=='\n')return i;return b.Length;}
        static int CsiNumber(string parameters,int fallback){if(string.IsNullOrEmpty(parameters))return fallback;string first=parameters.TrimStart('?').Split(';')[0];int value;return int.TryParse(first,out value)&&value>0?value:fallback;}
        static int[] CsiNumbers(string parameters){return (parameters??"").TrimStart('?').Split(';').Select(x=>{int n;return int.TryParse(x,out n)?n:0;}).ToArray();}
        void WriteTerminalChar(TerminalState state,char c){state.Cursor=Math.Max(0,Math.Min(state.Cursor,state.Screen.Length));while(state.Cursor>state.Screen.Length)state.Screen.Append(' ');if(state.Cursor<state.Screen.Length){if(state.Screen[state.Cursor]=='\n')state.Screen.Insert(state.Cursor,c);else state.Screen[state.Cursor]=c;}else state.Screen.Append(c);state.Cursor++;}
        void MoveTerminalVertical(TerminalState state,int direction,int count){while(count-->0){int start=TerminalLineStart(state.Screen,state.Cursor),column=state.Cursor-start;if(direction<0){if(start==0)break;int previousEnd=start-1,previousStart=TerminalLineStart(state.Screen,Math.Max(0,previousEnd));state.Cursor=Math.Min(previousStart+column,previousEnd);}else{int end=TerminalLineEnd(state.Screen,state.Cursor);if(end>=state.Screen.Length)break;int nextStart=end+1,nextEnd=TerminalLineEnd(state.Screen,nextStart);state.Cursor=Math.Min(nextStart+column,nextEnd);}}}
        void HandleCsi(TerminalState state,string parameters,char command){
            int count=CsiNumber(parameters,1);int start,end,mode;int[] values;
            switch(command){
                case 'A':MoveTerminalVertical(state,-1,count);break;case 'B':MoveTerminalVertical(state,1,count);break;
                case 'C':end=TerminalLineEnd(state.Screen,state.Cursor);state.Cursor=Math.Min(end,state.Cursor+count);break;
                case 'D':start=TerminalLineStart(state.Screen,state.Cursor);state.Cursor=Math.Max(start,state.Cursor-count);break;
                case 'G':case '`':start=TerminalLineStart(state.Screen,state.Cursor);end=TerminalLineEnd(state.Screen,state.Cursor);state.Cursor=Math.Min(end,start+count-1);break;
                case 'H':case 'f':values=CsiNumbers(parameters);int row=values.Length>0&&values[0]>0?values[0]:1,col=values.Length>1&&values[1]>0?values[1]:1;state.Cursor=0;while(--row>0){end=TerminalLineEnd(state.Screen,state.Cursor);if(end==state.Screen.Length)state.Screen.Append('\n');state.Cursor=end+1;}end=TerminalLineEnd(state.Screen,state.Cursor);state.Cursor=Math.Min(end,state.Cursor+col-1);break;
                case 'J':mode=CsiNumber(parameters,0);if(mode==2||mode==3){state.Screen.Clear();state.Cursor=0;}else if(mode==0&&state.Cursor<state.Screen.Length)state.Screen.Remove(state.Cursor,state.Screen.Length-state.Cursor);else if(mode==1&&state.Cursor>0){state.Screen.Remove(0,state.Cursor);state.Cursor=0;}break;
                case 'K':mode=CsiNumber(parameters,0);start=TerminalLineStart(state.Screen,state.Cursor);end=TerminalLineEnd(state.Screen,state.Cursor);if(mode==0&&end>state.Cursor)state.Screen.Remove(state.Cursor,end-state.Cursor);else if(mode==1){for(int p=start;p<=state.Cursor&&p<state.Screen.Length&&state.Screen[p]!='\n';p++)state.Screen[p]=' ';}else if(mode==2){state.Screen.Remove(start,end-start);state.Cursor=start;}break;
                case 'P':end=TerminalLineEnd(state.Screen,state.Cursor);if(end>state.Cursor)state.Screen.Remove(state.Cursor,Math.Min(count,end-state.Cursor));break;
                case 'X':end=TerminalLineEnd(state.Screen,state.Cursor);for(int p=state.Cursor;p<Math.Min(end,state.Cursor+count);p++)state.Screen[p]=' ';break;
                case '@':for(int p=0;p<count;p++)state.Screen.Insert(state.Cursor,' ');break;
                case 's':state.SavedCursor=state.Cursor;break;case 'u':state.Cursor=Math.Max(0,Math.Min(state.SavedCursor,state.Screen.Length));break;
            }
        }
        void TerminalEnded(TerminalState state){if(state.Ended)return;state.Ended=true;state.SavedPassword=null;state.Output.AppendText("\n\n[Session closed]");state.Output.ScrollToEnd();UpdateTerminalCount();}
        void CloseTerminal(TabItem tab){TerminalState state;if(!terminalSessions.TryGetValue(tab,out state))return;terminalSessions.Remove(tab);try{state.Session.Dispose();}catch{}terminalTabs.Items.Remove(tab);UpdateTerminalCount();if(terminalTabs.Items.Count==0)ShowConnections();}
        void CloseAllTerminals(){foreach(var state in terminalSessions.Values.ToList())try{state.Session.Dispose();}catch{}terminalSessions.Clear();}
