        void UpdateTerminalCount(){if(terminalCount!=null)terminalCount.Text=terminalSessions.Count+" open";}
        string BuildTerminalCommand(Connection connection,bool sftp){string exe=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"OpenSSH",sftp?"sftp.exe":"ssh.exe");if(!File.Exists(exe))exe=sftp?"sftp.exe":"ssh.exe";var b=new StringBuilder(QuoteCommand(exe));b.Append(sftp?" -P ":" -p ").Append(connection.Port);b.Append(" -o StrictHostKeyChecking=accept-new");if(!string.IsNullOrWhiteSpace(connection.KeyFile))b.Append(" -i ").Append(QuoteCommand(connection.KeyFile));b.Append(' ').Append(QuoteCommand(connection.UserName+"@"+connection.HostName));if(!sftp&&!string.IsNullOrWhiteSpace(connection.StartupCommand))b.Append(' ').Append(QuoteCommand(connection.StartupCommand));return b.ToString();}
        string QuoteCommand(string value){return "\""+(value??"").Replace("\"","\\\"")+"\"";}
        void ImportConfig(){var d=new OpenFileDialog{Title="Import OpenSSH config",Filter="SSH config|config;*.conf|All files|*.*"};if(d.ShowDialog(window)!=true)return;Connection c=null;foreach(var raw in File.ReadAllLines(d.FileName)){var line=raw.Trim();if(line.Length==0||line.StartsWith("#"))continue;var p=line.Split(new[]{' ','\t'},2,StringSplitOptions.RemoveEmptyEntries);if(p.Length<2)continue;if(p[0].Equals("Host",StringComparison.OrdinalIgnoreCase)){if(c!=null&&!c.Name.Contains("*"))all.Add(c);c=new Connection{Id=Guid.NewGuid().ToString(),Name=p[1],HostName=p[1],UserName=Environment.UserName,Port=22,Group="Imported",AuthType="SSH agent",CreatedAt=DateTime.UtcNow.ToString("o")};}else if(c!=null){if(p[0].Equals("HostName",StringComparison.OrdinalIgnoreCase))c.HostName=p[1];if(p[0].Equals("User",StringComparison.OrdinalIgnoreCase))c.UserName=p[1];int port;if(p[0].Equals("Port",StringComparison.OrdinalIgnoreCase)&&int.TryParse(p[1],out port))c.Port=port;if(p[0].Equals("IdentityFile",StringComparison.OrdinalIgnoreCase)){c.KeyFile=p[1].Replace("~",Environment.GetFolderPath(Environment.SpecialFolder.UserProfile));c.AuthType="Private key";}}}if(c!=null&&!c.Name.Contains("*"))all.Add(c);Save();Refresh();}
        void ExportConfig(){var d=new SaveFileDialog{Title="Export OpenSSH config",FileName="config",Filter="SSH config|config|All files|*.*"};if(d.ShowDialog(window)!=true)return;var b=new StringBuilder("# Exported by SSH Manager\r\n\r\n");foreach(var c in all){b.AppendLine("Host "+c.Name.Replace(' ','-'));b.AppendLine("    HostName "+c.HostName);b.AppendLine("    User "+c.UserName);b.AppendLine("    Port "+c.Port);if(!string.IsNullOrEmpty(c.KeyFile))b.AppendLine("    IdentityFile "+c.KeyFile);b.AppendLine();}File.WriteAllText(d.FileName,b.ToString());}
        void PreviewTerminals(){foreach(var c in all.Take(2)){var state=CreateTerminalView(c,false);state.Output.Text="Connecting to "+c.UserName+"@"+c.HostName+"...\n\nWelcome to "+c.Name+"\nLast login: today\n\n"+c.UserName+"@"+c.Name.ToLowerInvariant().Replace(' ','-')+":~$ ";terminalSessions[state.Tab]=state;terminalTabs.Items.Add(state.Tab);}terminalTabs.SelectedIndex=0;UpdateTerminalCount();mainGrid.Visibility=Visibility.Collapsed;terminalWorkspace.Visibility=Visibility.Visible;}
        void SaveVisualPng(Visual visual,int width,int height,string path){var bmp=new RenderTargetBitmap(Math.Max(1,width),Math.Max(1,height),96,96,PixelFormats.Pbgra32);bmp.Render(visual);using(var fs=File.Create(path)){var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bmp));enc.Save(fs);}}
        void Screenshot(){
            if(ScreenshotPath.IndexOf("compact",StringComparison.OrdinalIgnoreCase)>=0){window.Width=window.MinWidth;window.Height=window.MinHeight;}
            if(all.Count<4){all.Add(new Connection{Id="preview-1",Name="Production Web",Group="Production",HostName="web.example.com",Port=22,UserName="deploy",AuthType="Private key",Favorite=true,Notes="Primary application server.",Status="Online"});all.Add(new Connection{Id="preview-2",Name="Analytics DB",Group="Production",HostName="db.internal",Port=2222,UserName="analyst",AuthType="SSH agent",Status="Offline"});all.Add(new Connection{Id="preview-3",Name="Development",Group="Development",HostName="devbox.local",Port=22,UserName="developer",AuthType="Password",Status="Online"});Refresh();hosts.SelectedIndex=0;}
            if(ScreenshotPath.IndexOf("delete",StringComparison.OrdinalIgnoreCase)>=0)DeleteSelected();if(ScreenshotPath.IndexOf("wizard",StringComparison.OrdinalIgnoreCase)>=0)OpenWizard(null);if(ScreenshotPath.IndexOf("terminal",StringComparison.OrdinalIgnoreCase)>=0)PreviewTerminals();
            window.Dispatcher.BeginInvoke(new Action(()=>{Responsive();window.UpdateLayout();if(ScreenshotPath.IndexOf("commandmenu",StringComparison.OrdinalIgnoreCase)>=0){OpenCommandMenu();window.Dispatcher.BeginInvoke(new Action(()=>{commandMenu.UpdateLayout();SaveVisualPng(commandMenu,(int)Math.Ceiling(commandMenu.ActualWidth),(int)Math.Ceiling(commandMenu.ActualHeight),ScreenshotPath);commandMenu.IsOpen=false;window.Close();}),System.Windows.Threading.DispatcherPriority.ContextIdle);}else{SaveVisualPng(window,(int)window.ActualWidth,(int)window.ActualHeight,ScreenshotPath);window.Close();}}),System.Windows.Threading.DispatcherPriority.ApplicationIdle);
        }
    }
}
